/// The gallery's example of `Canvas`, with its settings taken from the story.
#[allow(unused_variables, unused_mut, clippy::redundant_clone, clippy::let_and_return, clippy::clone_on_copy)]
fn render(args: &Args) -> AnyView {
    Box::new({
        {
            let mut it = Canvas::new(|frame, scene| {
                for i in 0..8 {
                    let x = frame.x() + i as f32 * 28.0;
                    let height = 20.0 + i as f32 * 12.0;
                    let bar = Rect::new(x, frame.max_y() - height, 22.0, height);
                    // ravenrs-lint: allow(raw_color) a Canvas paints plain colors: it is drawing, with no theme to read
                    scene.push_quad(Quad::new(bar, Color::rgb(0.3, 0.4, 0.93)).radius(4.0));
                }
            })
            .size(240.0, 130.0);
            it
        }
    })
}

impl ComponentBook for Canvas {
    fn book() -> Meta {
        Meta::new("Media/Canvas", render)
            .summary("Box that draws whatever its closure appends to the scene.")
            .story("Example", Args::new())
    }
}
